        "explanationEn":  "In the second column, (كَانَ) is prefixed to the noun/attribute, adding the meaning of \u0027was\u0027. The predicate describing this state changes from Tanween Dammah (دو پیش) to Tanween Fatha (دو زبر), written orthographically with an added Alif (e.g. رَسُولًا). Crucially, in Arabic idiom and specifically regarding divine attributes, (كَانَ) denotes continuous, permanent reality (\u0027is indeed\u0027) rather than past cessation, meaning \u0027Allah is indeed All-Knowing and All-Wise\u0027.",
