        "primaryMeaningEn":  "To express a quantity of exactly two, Arabic appends the dual suffix -āni (nominative) or -ayni (oblique).",
        "caseEffectUr":  "حالتِ رفع میں الف اور نون مکسور (ـَانِ) اور حالتِ نصب و جر میں یاء ماقبل مفتوح اور نون مکسور (ـَيْنِ)۔",
        "caseEffectEn":  "The dual takes -āni in the nominative case and -ayni in the accusative and genitive cases.",
        "explanationUr":  "عربی لفظ کی تعداد دو (۲) ظاہر کرنے کیلئے اسکے آخر میں الف اور نون (انِ) کا اضافہ ہوتا ہے، جیسا کہ درج بالا مثالوں سے واضح ہے۔ ایسے الفاظ میں آخر میں موجود (انِ) کبھی بدل کر (ینِ) بن جاتے ہیں لیکن اس لفظی تبدیلی کا عموماً معنی پر اثر نہیں ہوتا، جیسے: الْمَشْرِقَانِ / الْمَشْرِقَيْنِ، الْمَغْرِبَانِ / الْمَغْرِبَيْنِ، الْوَالِدَانِ / الْوَالِدَيْنِ، الْجَنَّتَانِ / الْجَنَّتَيْنِ۔",
        "explanationEn":  "To denote the dual number (exactly two), the suffix -āni is added to the singular noun (e.g. Al-Mashriqān = the two easts). In the accusative and genitive cases, the suffix changes to -ayni (e.g. Al-Mashriqayn). This inflectional variation marks syntactic case without changing the dual meaning.",
